import{_ as t,o as a,c as n,a5 as r}from"./chunks/framework.bIR-4glx.js";const h=JSON.parse('{"title":"A Sustainable Small Business: Scope, Pricing, Delivery, Payment, and Capacity","description":"Use a defined service and hypothetical numbers to examine pricing, total working time, the remainder from each delivery, payment timing, and capacity within a manageable level of effort.","frontmatter":{"title":"A Sustainable Small Business: Scope, Pricing, Delivery, Payment, and Capacity","description":"Use a defined service and hypothetical numbers to examine pricing, total working time, the remainder from each delivery, payment timing, and capacity within a manageable level of effort.","updated":"2026-09-19T00:00:00.000Z"},"headers":[],"relativePath":"en/threads/practice/sustainable-business.md","filePath":"en/threads/practice/sustainable-business.md","lastUpdated":1789776000000}'),i={name:"en/threads/practice/sustainable-business.md"};function o(s,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="a-sustainable-small-business" tabindex="-1">A Sustainable Small Business <a class="header-anchor" href="#a-sustainable-small-business" aria-label="Permalink to &quot;A Sustainable Small Business&quot;">​</a></h1><p><a href="./customer-discovery">Finding first customers</a> asks whether someone needs an outcome and will try it once. Sustainability also asks whether you can deliver as promised, receive payment, and retain enough capacity for the next customer. Orders, revenue, payments received, and available time are different records. One cannot stand in for the others.</p><p>This page supplements <a href="./../part-2/entrepreneurship">Entrepreneurship</a> and <a href="./../part-3/2-ai-development-and-resource-layer">AI Learning, Development, and Resource-layer Entrepreneurship</a> with practical records for their delivery and operating questions. It is an exercise in observing operations. All numbers are hypothetical, and the framework is a suggestion from this guide. The examples omit complete tax, accounting, and contract treatment; they cannot establish actual net profit or replace professional advice.</p><h2 id="_1-define-the-service-boundary" tabindex="-1">1. Define the Service Boundary <a class="header-anchor" href="#_1-define-the-service-boundary" aria-label="Permalink to &quot;1. Define the Service Boundary&quot;">​</a></h2><p>Replace “help you use AI well” with a service that can be accepted: create an internal retrieval prototype from one authorized collection of materials in the required format, delivering a demonstration, test records, and operating instructions. Production deployment, ongoing maintenance, extra data, and additional training need separate agreement. Vague boundaries make it easier for the two parties to disagree about completion.</p><p>A service description should identify who it suits, the task it solves, what the customer supplies, deliverables, acceptance conditions, quantity and timing, included revisions, and what happens outside the scope. Also explain when it does not fit, such as when necessary materials are unavailable or the customer needs a response time you cannot promise.</p><p>When a new request arrives, distinguish an original deliverable that failed its agreement, a revision within the original scope, and genuinely additional work. Do not charge extra merely to correct your own omission, or quietly turn a finite service into an unlimited commitment. Confirm the impact and revised arrangements before beginning additional work.</p><h2 id="_2-treat-pricing-as-an-experiment" tabindex="-1">2. Treat Pricing as an Experiment <a class="header-anchor" href="#_2-treat-pricing-as-an-experiment" aria-label="Permalink to &quot;2. Treat Pricing as an Experiment&quot;">​</a></h2><p>A pricing assumption can be phrased as: “Will target customers accept this price for this scope, while actual delivery stays within the effort limit?” Show the price and scope clearly. Record people contacted, formal quotes, acceptances, reasons for declining, and payments actually received.</p><p>Keep the service scope similar within a round. Changing the audience, channel, price, and deliverables together makes a conversion change difficult to explain. A small sample cannot provide a precise demand curve. A missed sale may reflect timing, trust, or internal approval rather than price. Do not interpret every refusal as “too expensive.”</p><p>Give discounts a clear scope and end date. Do not invent original prices or limited places. Acceptance of a pilot price still leaves the regular price untested. When comparing quotes, record differences in customer circumstances; two different customers do not form a controlled experiment.</p><h2 id="_3-include-your-own-time" tabindex="-1">3. Include Your Own Time <a class="header-anchor" href="#_3-include-your-own-time" aria-label="Permalink to &quot;3. Include Your Own Time&quot;">​</a></h2><p>Suppose one information-organizing service costs 1,200 yuan and payment has been received in full. First record the spending and working time attributable to that order:</p><table tabindex="0"><thead><tr><th>Item</th><th>Assumed amount or time</th></tr></thead><tbody><tr><td>Tools and external processing</td><td>120 yuan</td></tr><tr><td>External assistance</td><td>80 yuan</td></tr><tr><td>Customer acquisition cash spending allocated to this order</td><td>150 yuan</td></tr><tr><td>Communication and quotation</td><td>1 hour</td></tr><tr><td>Material preparation</td><td>1 hour</td></tr><tr><td>Production</td><td>3 hours</td></tr><tr><td>Revisions</td><td>1 hour</td></tr><tr><td>Handover and subsequent support</td><td>1 hour</td></tr></tbody></table><p>The listed cash spending is <code>120 + 80 + 150 = 350 yuan</code>, leaving <code>1,200 - 350 = 850 yuan</code>. Total working time is <code>7 hours</code>, not just the <code>3 hours</code> spent on production.</p><p>To examine the cost of time, suppose you use an internal comparison value of 80 yuan per hour for your own work. The order&#39;s time value is then <code>7 × 80 = 560 yuan</code>, leaving <code>850 - 560 = 290 yuan</code> after subtracting it. The hourly value is an illustrative assumption, not a wage recommendation. Your own work does not become costless merely because it does not require an immediate cash payment.</p><p>That 290 yuan is before shared fixed expenses, unallocated experiments, taxes, and other omitted costs. It is not net profit. If rework adds four hours, the same assumed time value adds 320 yuan and brings the remainder to <code>-30 yuan</code>. This shows why rework needs recording; it does not establish that the entire business must lose money.</p><p>Acquisition spending must also account for unsuccessful activity. The illustrative 150 yuan already includes an allocation of failed attempts from that period. In practice, keep the allocation method visible so that apparently positive orders do not hide falling cash across the business.</p><h2 id="_4-track-payment-and-commitments-together" tabindex="-1">4. Track Payment and Commitments Together <a class="header-anchor" href="#_4-track-payment-and-commitments-together" aria-label="Permalink to &quot;4. Track Payment and Commitments Together&quot;">​</a></h2><p>List quotations, accepted orders, delivery, acceptance, amounts due, payments received, and refunds separately. Work completed but not paid for differs from payment received for unfinished work. An advance payment raises the current balance while also creating an unfulfilled delivery obligation. It is not all freely available surplus.</p><p>A simple view of the next four weeks can show opening available cash, confirmed spending, expected payment dates, and unfinished commitments. Label the basis and uncertainty for expected payments. A verbal expression of interest is not confirmed collection. If a payment is delayed, check which commitments remain achievable and promptly agree on arrangements with the relevant people, instead of masking the gap with more untested orders.</p><p>Actual payment, refund, and contract arrangements need to fit the real business. This page concerns records that reflect reality; it offers no universal advance-payment percentage or borrowing recommendation.</p><h2 id="_5-capacity-depends-on-the-whole-process" tabindex="-1">5. Capacity Depends on the Whole Process <a class="header-anchor" href="#_5-capacity-depends-on-the-whole-process" aria-label="Permalink to &quot;5. Capacity Depends on the Whole Process&quot;">​</a></h2><p>Suppose twenty hours a week are available for the business, with six reserved for shared administration, learning, and unexpected work. Fourteen hours remain for the order process, including acquisition. At seven hours per order, calculated capacity is two orders. This is not a requirement to fill every week.</p><p>If one order adds four hours of rework that week, you cannot still assume all work fits within fourteen hours. Customer feedback delays, third-party scheduling, and batch work can also constrain delivery. Keep available working hours separate from promised completion dates. Before accepting another order, review existing commitments rather than looking only for blank calendar spaces.</p><p>Repeated overruns call for examining scope, input quality, revision rounds, and price. Remove steps that add no value while retaining necessary checks; do not eliminate essential acceptance work merely to make the numbers look better. Record AI-assisted time savings only after accounting for prompting, review, corrections, and maintenance.</p><h2 id="_6-observe-repeat-purchases-after-delivery" tabindex="-1">6. Observe Repeat Purchases After Delivery <a class="header-anchor" href="#_6-observe-repeat-purchases-after-delivery" aria-label="Permalink to &quot;6. Observe Repeat Purchases After Delivery&quot;">​</a></h2><p>Acceptance must be executable. It might require complete agreed fields, successful sample checks, and instructions the customer can follow. “Until satisfied” does not help plan delivery or explain costs. At handover, record the version, known limitations, the person confirming acceptance, unresolved issues, and support boundaries.</p><p>A repeat purchase means someone bought an outcome again, but record why. A weekly recurring task, work needed because the first order was incomplete, and a promotion have different meanings. No repeat purchase does not automatically mean delivery failed: a genuinely one-time task may need no second order.</p><p>Set aside a regular weekly session to reconcile actual order hours, payments received, rework, unfinished commitments, and feedback. Choose one main issue for the next week. If materials are incomplete, improve the input checklist. If quality is inconsistent, narrow the service scope first.</p><h2 id="_7-set-conditions-for-continuing" tabindex="-1">7. Set Conditions for Continuing <a class="header-anchor" href="#_7-set-conditions-for-continuing" aria-label="Permalink to &quot;7. Set Conditions for Continuing&quot;">​</a></h2><p>Use the <a href="./../../templates/startup-experiment">Startup Experiment Card</a> to state time and spending limits for the round and conditions that pause new orders: existing promises can no longer be kept, essential materials cannot be used with permission, or rework repeatedly exceeds manageable limits. Stopping new commitments does not remove existing responsibilities; handover and explanation still matter.</p><p>Evidence for continuing can include repeatable delivery within similar scope, increasingly predictable total hours, payments arriving as agreed, and room for support and exceptions. These records explain the next step better than “We were really busy this month.” For more AI service contexts, see <a href="./../part-3/2-ai-development-and-resource-layer">Development and Resource-layer Entrepreneurship</a>; for personal experience, see <a href="./../part-2/entrepreneurship">Entrepreneurship</a>.</p><h2 id="explain-one-order-in-english" tabindex="-1">Explain One Order in English <a class="header-anchor" href="#explain-one-order-in-english" aria-label="Permalink to &quot;Explain One Order in English&quot;">​</a></h2><blockquote><p>The service brought in 1,200 yuan and required seven hours of work. After the listed cash costs and an assumed value for our time, 290 yuan remained before shared overhead and other uncounted costs. That is not net profit. We need to reduce unplanned revisions before increasing capacity.</p></blockquote><p>Useful terms: <strong>scope of work</strong> (工作范围), <strong>acceptance criteria</strong> (验收标准), <strong>rework</strong> (返工), <strong>payment received</strong> (已到账款项), and <strong>delivery capacity</strong> (交付容量).</p>',36)])])}const m=t(i,[["render",o]]);export{h as __pageData,m as default};
